  internal TurtleView(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw|ControlStyles.Selectable,true);BackColor=Color.White;TabStop=true;AccessibleName="Disegno della tartaruga";AccessibleDescription="Rotella o tasti più e meno per zoom. Trascina o usa le frecce per spostare. Home mostra tutto.";motion=new MotionValue(this,1);cameraX=new MotionValue(this);cameraY=new MotionValue(this);cameraW=new MotionValue(this,100);cameraH=new MotionValue(this,100);zoomMotion=new MotionValue(this,1);panXMotion=new MotionValue(this);panYMotion=new MotionValue(this);}
  internal void Bind(FlowTurtle next){if(ReferenceEquals(turtle,next)&&revision==(next==null?-1:next.Revision))return;if(clearGhost!=null){clearGhost.Dispose();clearGhost=null;}if(ReferenceEquals(turtle,next)&&next!=null&&next.Segments.Count<count&&UiMotion.Enabled&&Visible&&IsHandleCreated&&Width>0&&Height>0){var ghost=new Bitmap(Width,Height);DrawToBitmap(ghost,ClientRectangle);clearGhost=ghost;}double t=Math.Max(0,Math.Min(1,motion.Value));fromX=fromX+(x-fromX)*t;fromY=fromY+(y-fromY)*t;fromHeading=fromHeading+(heading-fromHeading)*t;bool same=ReferenceEquals(turtle,next);tail=same&&next!=null&&next.Segments.Count==count+1;turtle=next;revision=next==null?-1:next.Revision;count=next==null?0:next.Segments.Count;x=next==null?0:next.X;y=next==null?0:next.Y;double angle=next==null?90:next.Heading;heading=fromHeading+((angle-fromHeading+540)%360+360)%360-180;if(!same){cachedRevision=-2;fromX=x;fromY=y;fromHeading=heading;Fit();}var box=SceneBounds(next==null?new List<FlowTurtle.Segment>():next.Segments,x,y);cameraX.Set((float)box[0]);cameraY.Set((float)box[1]);cameraW.Set((float)box[2]);cameraH.Set((float)box[3]);motion.Jump(0);motion.Set(1,280);Invalidate();}
  internal void Fit(){zoom=1;panX=panY=0;zoomMotion.Set(1);panXMotion.Set(0);panYMotion.Set(0);Invalidate();}internal void Zoom(double factor){zoom=Math.Max(.1,Math.Min(40,zoom*factor));zoomMotion.Set((float)zoom);Invalidate();}
  protected override void OnMouseWheel(MouseEventArgs e){Zoom(e.Delta>0?1.2:1/1.2);base.OnMouseWheel(e);}protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Left){Focus();drag=e.Location;dragging=true;Capture=true;}base.OnMouseDown(e);}protected override void OnMouseMove(MouseEventArgs e){if(dragging){panX+=e.X-drag.X;panY+=e.Y-drag.Y;drag=e.Location;panXMotion.Jump((float)panX);panYMotion.Jump((float)panY);Invalidate();}base.OnMouseMove(e);}protected override void OnMouseUp(MouseEventArgs e){dragging=false;Capture=false;base.OnMouseUp(e);}protected override void OnMouseCaptureChanged(EventArgs e){if(!Capture)dragging=false;base.OnMouseCaptureChanged(e);}
  protected override bool IsInputKey(Keys k){return k==Keys.Left||k==Keys.Right||k==Keys.Up||k==Keys.Down||base.IsInputKey(k);}protected override void OnKeyDown(KeyEventArgs e){switch(e.KeyCode){case Keys.Add:case Keys.Oemplus:Zoom(1.2);break;case Keys.Subtract:case Keys.OemMinus:Zoom(1/1.2);break;case Keys.Home:Fit();break;case Keys.Left:panX+=25;break;case Keys.Right:panX-=25;break;case Keys.Up:panY+=25;break;case Keys.Down:panY-=25;break;default:base.OnKeyDown(e);return;}e.Handled=true;panXMotion.Set((float)panX);panYMotion.Set((float)panY);Invalidate();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Width<1||Height<1)return;double p=Math.Max(0,Math.Min(1,motion.Value));var lines=turtle==null?new List<FlowTurtle.Segment>():turtle.Segments;double cx=fromX+(x-fromX)*motion.Value,cy=fromY+(y-fromY)*motion.Value,ch=fromHeading+(heading-fromHeading)*motion.Value;double[] b={cameraX.Value,cameraY.Value,Math.Max(1,cameraW.Value),Math.Max(1,cameraH.Value)};
   int bw=Math.Min(2400,Math.Max(1,Width)),bh=Math.Min(1800,Math.Max(1,Height));if(cachedLines==null||cachedRevision!=revision||cachedLines.Width!=bw||cachedLines.Height!=bh){if(cachedLines!=null)cachedLines.Dispose();cachedLines=new Bitmap(bw,bh);cacheBounds=SceneBounds(lines,x,y);using(var g=Graphics.FromImage(cachedLines))Draw(g,cachedLines.Size,lines,x,y,x,y,heading,tail?0:1,1,0,0,false,cacheBounds);cachedRevision=revision;}
   var graphics=e.Graphics;graphics.Clear(Color.White);graphics.SmoothingMode=SmoothingMode.AntiAlias;double scale=Math.Max(.000001,Math.Min(Math.Max(1,Width-54)/b[2],Math.Max(1,Height-54)/b[3]))*zoomMotion.Value;
   double sourceScale=Math.Max(.000001,Math.Min(Math.Max(1,bw-54)/cacheBounds[2],Math.Max(1,bh-54)/cacheBounds[3])),ratio=scale/sourceScale;float imageX=(float)(Width/2+(cacheBounds[0]-b[0])*scale+panXMotion.Value-bw*ratio/2),imageY=(float)(Height/2-(cacheBounds[1]-b[1])*scale+panYMotion.Value-bh*ratio/2);if(Math.Abs(ratio-1)<.00001)graphics.DrawImageUnscaled(cachedLines,(int)Math.Round(imageX),(int)Math.Round(imageY));else graphics.DrawImage(cachedLines,new RectangleF(imageX,imageY,(float)(bw*ratio),(float)(bh*ratio)));
   Func<double,double,PointF> point=(px,py)=>new PointF((float)(Width/2+(px-b[0])*scale+panXMotion.Value),(float)(Height/2-(py-b[1])*scale+panYMotion.Value));if(tail&&lines.Count>0){var last=lines[lines.Count-1];using(var pen=new Pen(ColorTranslator.FromHtml(last.Color),2){StartCap=LineCap.Round,EndCap=LineCap.Round})graphics.DrawLine(pen,point(last.X1,last.Y1),point(last.X1+(last.X2-last.X1)*p,last.Y1+(last.Y2-last.Y1)*p));}
   PointF pos=point(cx,cy);double a=ch*Math.PI/180;var triangle=new PointF[3];double[] angles={a,a+2.5,a-2.5};for(int i=0;i<3;i++)triangle[i]=new PointF(pos.X+(float)(Math.Cos(angles[i])*10),pos.Y-(float)(Math.Sin(angles[i])*10));using(var brush=new SolidBrush(Color.FromArgb(80,133,240)))using(var pen=new Pen(Color.FromArgb(34,52,80),1.4f)){graphics.FillPolygon(brush,triangle);graphics.DrawPolygon(pen,triangle);}if(clearGhost!=null){if(p>=1){clearGhost.Dispose();clearGhost=null;}else using(var attributes=new ImageAttributes()){var color=new ColorMatrix();color.Matrix33=(float)(1-p);attributes.SetColorMatrix(color);graphics.DrawImage(clearGhost,ClientRectangle,0,0,clearGhost.Width,clearGhost.Height,GraphicsUnit.Pixel,attributes);}}if(Focused)ControlPaint.DrawFocusRectangle(graphics,Rectangle.Inflate(ClientRectangle,-3,-3));
  }
  internal static double[] SceneBounds(IList<FlowTurtle.Segment> lines,double x,double y){double minX=Math.Min(0,x),maxX=Math.Max(0,x),minY=Math.Min(0,y),maxY=Math.Max(0,y);foreach(var s in lines){minX=Math.Min(minX,Math.Min(s.X1,s.X2));maxX=Math.Max(maxX,Math.Max(s.X1,s.X2));minY=Math.Min(minY,Math.Min(s.Y1,s.Y2));maxY=Math.Max(maxY,Math.Max(s.Y1,s.Y2));}double w=Math.Max(100,maxX-minX),h=Math.Max(100,maxY-minY);return new[]{(minX+maxX)/2,(minY+maxY)/2,w,h};}
  internal static void Draw(Graphics g,Size size,IList<FlowTurtle.Segment> lines,double x,double y,double cx,double cy,double heading,double tail,double zoom,double panX,double panY,bool cursor,double[] fitted=null){g.Clear(Color.White);g.SmoothingMode=SmoothingMode.AntiAlias;var b=fitted??SceneBounds(lines,x,y);double scale=Math.Max(.000001,Math.Min(Math.Max(1,size.Width-54)/b[2],Math.Max(1,size.Height-54)/b[3]))*zoom;Func<double,double,PointF> point=(px,py)=>new PointF((float)(size.Width/2+(px-b[0])*scale+panX),(float)(size.Height/2-(py-b[1])*scale+panY));
   // Reuse pens by color. No idle timer, snapshots or per-segment pen allocation.
   var pens=new Dictionary<string,Pen>();try{for(int i=0;i<lines.Count;i++){var s=lines[i];Pen pen;if(!pens.TryGetValue(s.Color,out pen)){pen=new Pen(ColorTranslator.FromHtml(s.Color),2){StartCap=LineCap.Round,EndCap=LineCap.Round};pens.Add(s.Color,pen);}double t=i==lines.Count-1?tail:1;g.DrawLine(pen,point(s.X1,s.Y1),point(s.X1+(s.X2-s.X1)*t,s.Y1+(s.Y2-s.Y1)*t));}}finally{foreach(var pen in pens.Values)pen.Dispose();}
   if(cursor){PointF pos=point(cx,cy);double a=heading*Math.PI/180;PointF[] triangle=new PointF[3];double[] angles={a,a+2.5,a-2.5};for(int i=0;i<3;i++)triangle[i]=new PointF(pos.X+(float)(Math.Cos(angles[i])*10),pos.Y-(float)(Math.Sin(angles[i])*10));using(var brush=new SolidBrush(Color.FromArgb(80,133,240)))using(var pen=new Pen(Color.FromArgb(34,52,80),1.4f)){g.FillPolygon(brush,triangle);g.DrawPolygon(pen,triangle);}}
  }
  internal static Bitmap Render(FlowTurtle.Snapshot snapshot,int width,int height){if(width<64||height<64||width>4096||height>4096)throw new ArgumentOutOfRangeException("width");var image=new Bitmap(width,height);try{using(var g=Graphics.FromImage(image))Draw(g,new Size(width,height),snapshot.Segments,snapshot.X,snapshot.Y,snapshot.X,snapshot.Y,snapshot.Heading,1,1,0,0,false);return image;}catch{image.Dispose();throw;}}
  protected override void Dispose(bool disposing){if(disposing){if(clearGhost!=null)clearGhost.Dispose();if(cachedLines!=null)cachedLines.Dispose();motion.Dispose();cameraX.Dispose();cameraY.Dispose();cameraW.Dispose();cameraH.Dispose();zoomMotion.Dispose();panXMotion.Dispose();panYMotion.Dispose();}base.Dispose(disposing);}
