 internal sealed partial class MainForm {
  FlowButton turtlePlay;RuntimeSurface turtleCard;TurtleView turtleView,turtleLarge;Label turtleReadout;Form turtleWindow;
  private bool HasTurtle(){return Project!=null&&(Project.Nodes.Any(n=>FlowTurtle.IsTurtle(n.Kind))||Project.Functions!=null&&Project.Functions.Any(f=>f.Body.Nodes.Any(n=>FlowTurtle.IsTurtle(n.Kind))));}
  private void BuildRuntimeTurtle(){turtleCard=new RuntimeSurface();turtleCard.Name="TurtleCard";runtimePanel.Controls.Add(turtleCard);turtleReadout=Ui.Label("DISEGNO · TARTARUGA",9,Ui.Muted,true);turtleCard.Controls.Add(turtleReadout);turtleView=new TurtleView();turtleCard.Controls.Add(turtleView);var expand=Ui.Button("Espandi disegno",130,ShowTurtle);expand.Name="ExpandTurtle";turtleCard.Controls.Add(expand);var save=Ui.Button("Salva SVG",110,()=>SaveTurtle(false));save.Name="SaveTurtle";turtleCard.Controls.Add(save);}
  private int LayoutRuntimeTurtle(int y,int w){if(turtlePlay!=null)turtlePlay.Text=runTimer.Enabled?"Pausa":"Esegui";if(turtleWindow!=null&&Runner!=null&&(Runner.State==RuntimeState.WaitingForInput||Runner.State==RuntimeState.WaitingForFile)){turtleWindow.Close();Activate();}turtleCard.Visible=HasTurtle()||Runner!=null&&Runner.Turtle.Used;if(!turtleCard.Visible){turtleView.Bind(null);if(turtleLarge!=null)turtleLarge.Bind(null);return y;}turtleCard.SetBounds(S(12),y,w,S(306));turtleReadout.SetBounds(S(14),S(9),w-S(28),S(28));turtleView.SetBounds(S(12),S(42),w-S(24),S(200));turtleCard.Controls["ExpandTurtle"].SetBounds(S(12),S(252),(w-S(32))/2,S(38));turtleCard.Controls["SaveTurtle"].SetBounds(S(20)+(w-S(32))/2,S(252),(w-S(32))/2,S(38));var t=Runner==null?null:Runner.Turtle;turtleView.Bind(t);if(turtleLarge!=null&&!turtleLarge.IsDisposed)turtleLarge.Bind(t);turtleReadout.Text=t==null?"DISEGNO · TARTARUGA":"X "+ValueFormatter.Format(t.X)+"  ·  Y "+ValueFormatter.Format(t.Y)+"  ·  "+ValueFormatter.Format(t.Heading)+"°";return y+S(318);}
  private void ShowTurtle(){if(turtleWindow!=null&&!turtleWindow.IsDisposed){turtleWindow.Activate();return;}turtleWindow=new Form{Text="Disegno della tartaruga — Frociart",Size=new Size(820,650),MinimumSize=new Size(460,420),StartPosition=FormStartPosition.CenterParent,BackColor=Ui.Surface,ShowInTaskbar=false,Icon=Icon};turtleLarge=new TurtleView{Dock=DockStyle.Fill};turtleWindow.Controls.Add(turtleLarge);var toolbar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=92,Padding=new Padding(10),BackColor=Ui.Surface};toolbar.Controls.Add(Ui.Button("Tutto",80,()=>turtleLarge.Fit()));toolbar.Controls.Add(Ui.Button("−",50,()=>turtleLarge.Zoom(1/1.2)));toolbar.Controls.Add(Ui.Button("+",50,()=>turtleLarge.Zoom(1.2)));toolbar.Controls.Add(Ui.Button("PNG",80,()=>SaveTurtle(true)));toolbar.Controls.Add(Ui.Button("SVG",80,()=>SaveTurtle(false)));toolbar.Controls.Add(Ui.Button("Avanti",80,SingleStep));turtlePlay=Ui.Button(runTimer.Enabled?"Pausa":"Esegui",90,()=>{if(runTimer.Enabled)PauseRun();else StartRun();},true);toolbar.Controls.Add(turtlePlay);turtleWindow.Controls.Add(toolbar);turtleLarge.Bind(Runner==null?null:Runner.Turtle);turtleWindow.FormClosed+=delegate{turtleLarge=null;turtleWindow=null;turtlePlay=null;};Ui.ApplyTheme(turtleWindow);turtleWindow.Show(this);}
  private void SaveTurtle(bool png){if(Runner==null||!Runner.Turtle.Used){SetStatus("Esegui un comando tartaruga prima di salvare il disegno.");return;}PauseRun();var snapshot=Runner.Turtle.Capture();using(var save=new SaveFileDialog{Title="Salva disegno della tartaruga",Filter=png?"PNG (*.png)|*.png":"SVG (*.svg)|*.svg",DefaultExt=png?"png":"svg",AddExtension=true,FileName="Disegno_tartaruga",OverwritePrompt=true,RestoreDirectory=true}){if(save.ShowDialog(turtleWindow??this)!=DialogResult.OK)return;try{DiagramExport.WriteAtomically(save.FileName,path=>{if(png){using(var bitmap=TurtleView.Render(snapshot,1600,1200))bitmap.Save(path,ImageFormat.Png);}else File.WriteAllText(path,FlowTurtle.Svg(snapshot),new UTF8Encoding(false));});SetStatus("Disegno salvato.");}catch(Exception ex){ShowError("Disegno non salvato",ex);}}}
 }
